def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] == row[c + 1] and row[c] != row[c - 1]:
                # The repeated color is the pattern marker; replace only the
                # background cell between two consecutive markers.
                marker = row[c - 1]
                background = 8 if marker == 4 else 3
                if row[c] == background:
                    out[r][c] = 2
    return out
